import type { AboutSection, ContentItem, LocalizedText, MediaAsset, RegionContent, SiteData } from "./index";

// Public copy is deliberately required in every locale; there is no English fallback.
const t = (en: string, ar: string, fr: string, nl: string): LocalizedText => ({ en, ar, fr, nl });
const same = (value: string): LocalizedText => t(value, value, value, value);
const media = (id: string, file: string, alt: LocalizedText, focalX = 50, focalY = 50): MediaAsset => ({
  id, url: file.startsWith("/") ? file : `/starter-media/${file}`, alt, focalX, focalY, zoom: 1,
});
const section = (id: string, title: LocalizedText, body: LocalizedText, bullets?: LocalizedText[], image?: MediaAsset): AboutSection => ({ id, title, body, bullets, media: image });

function item(id: string, type: ContentItem["type"], title: LocalizedText, summary: LocalizedText, body: LocalizedText, cover?: MediaAsset, extras: Partial<ContentItem> = {}): ContentItem {
  return { id, type, slug: same(id), title, summary, body, cover, status: "published", ...extras };
}

function page(id: string, title: LocalizedText, summary: LocalizedText, body: LocalizedText, cover?: MediaAsset, extras: Partial<ContentItem> = {}): ContentItem {
  return item(id, "pages", title, summary, body, cover, {
    seo: {
      title,
      description: summary,
      keywords: t(
        "MOVERA, Belgium, mobility, autonomous vehicles, connected transport",
        "موفيرا، بلجيكا، التنقل، المركبات ذاتية القيادة، النقل المتصل",
        "MOVERA, Belgique, mobilité, véhicules autonomes, transport connecté",
        "MOVERA, België, mobiliteit, autonome voertuigen, verbonden vervoer",
      ),
    },
    ...extras,
  });
}

