const services: ContentItem[] = [
  item("autonomy-systems", "services", t("Autonomy Systems", "أنظمة القيادة الذاتية", "Systèmes autonomes", "Autonomiesystemen"), t("Build perception, planning and control that teams can test, explain and trust.", "نبني الإدراك والتخطيط والتحكم بطريقة قابلة للاختبار والتفسير والثقة.", "Concevoir une perception, une planification et un contrôle testables et explicables.", "Bouw perceptie, planning en aansturing die teams kunnen testen en uitleggen."), t("MOVERA connects sensor evidence, vehicle behaviour and human review in one engineering workflow.\nFrom operating domain to road-test evidence, clear gates guide safety, exceptions and release decisions.", "تربط موفيرا أدلة المستشعرات بسلوك المركبة والمراجعة البشرية ضمن مسار هندسي واحد.\nننتقل من نطاق التشغيل إلى أدلة الاختبار الميداني عبر بوابات واضحة للسلامة والاستثناءات وقرارات الإطلاق.", "MOVERA relie preuves capteurs, comportement du véhicule et revue humaine dans un même parcours d’ingénierie.\nDu domaine opérationnel aux essais routiers, des jalons clairs guident sécurité, exceptions et mise en service.", "MOVERA brengt sensorgegevens, voertuiggedrag en menselijke beoordeling samen in één engineeringflow.\nVan operationeel domein tot wegtestbewijs sturen duidelijke poorten veiligheid, uitzonderingen en vrijgave."), img.serviceAutonomy, { category: "Autonomy", sector: "Autonomous Vehicles", featured: true, displayOrder: 0, tags: ["perception", "planning", "validation"], relatedIds: ["perception-layer", "brussels-perception-pilot"] }),
  item("fleet-intelligence", "services", t("Fleet Intelligence", "ذكاء الأساطيل", "Intelligence de flotte", "Vlootintelligentie"), t("Turn live fleet signals into decisions before service is affected.", "نحوّل إشارات الأسطول الحية إلى قرارات قبل تأثر الخدمة.", "Transformer les signaux de flotte en décisions avant que le service ne soit touché.", "Zet live vlootsignalen om in beslissingen vóór de dienstverlening geraakt wordt."), t("MOVERA unifies vehicle health, charging, missions and route context without burying operators in dashboards.\nDispatch, maintenance and customer operations work from the same evidence and next action.", "توحّد موفيرا حالة المركبات والشحن والمهام وسياق المسارات من دون إغراق المشغّلين بلوحات المتابعة.\nتعمل فرق التوجيه والصيانة وخدمة العملاء انطلاقاً من الدليل نفسه والخطوة التالية نفسها.", "MOVERA réunit état des véhicules, recharge, missions et itinéraires sans noyer les opérateurs sous les tableaux de bord.\nDispatching, maintenance et opérations clients partagent la même preuve et la même prochaine action.", "MOVERA verenigt voertuigconditie, laden, opdrachten en routecontext zonder operatoren te verdrinken in dashboards.\nDispatching, onderhoud en klantoperaties werken met hetzelfde bewijs en dezelfde volgende actie."), img.serviceFleet, { category: "Operations", sector: "Fleet Operations", featured: true, displayOrder: 1, tags: ["fleet", "maintenance", "dispatch"], relatedIds: ["movera-command", "antwerp-fleet-flow"] }),
  item("mobility-operations", "services", t("Mobility Operations", "عمليات التنقل", "Opérations de mobilité", "Mobiliteitsoperaties"), t("Coordinate vehicles, people and infrastructure as one service in motion.", "ننسّق المركبات والأشخاص والبنية التحتية كخدمة واحدة تتحرك بانسجام.", "Coordonner véhicules, équipes et infrastructure comme un seul service en mouvement.", "Coördineer voertuigen, mensen en infrastructuur als één bewegende dienst."), t("Reliable mobility depends on handovers between vehicle and operator, depot and street, plan and exception.\nMOVERA makes those moments visible and gives each next action a clear owner.", "تعتمد موثوقية التنقل على انتقال المسؤولية بين المركبة والمشغّل، والمستودع والشارع، والخطة والاستثناء.\nتجعل موفيرا هذه اللحظات واضحة وتمنح كل إجراء تالٍ مسؤولاً معروفاً.", "La fiabilité se joue dans les relais entre véhicule et opérateur, dépôt et rue, plan et exception.\nMOVERA rend ces moments visibles et attribue clairement chaque action suivante.", "Betrouwbare mobiliteit draait om overdrachten tussen voertuig en operator, depot en straat, planning en uitzondering.\nMOVERA maakt die momenten zichtbaar en geeft elke volgende actie een duidelijke eigenaar."), img.serviceOperations, { category: "Operations", sector: "Connected Infrastructure", featured: true, displayOrder: 2, tags: ["orchestration", "exceptions", "service"], relatedIds: ["motion-os", "adaptive-mobility-corridor"] }),
  item("vehicle-experience", "services", t("Vehicle Experience", "تجربة المركبة", "Expérience à bord", "Voertuigervaring"), t("Design autonomous journeys that explain themselves at the right moment.", "نصمم رحلات ذاتية تشرح ما يحدث للراكب في اللحظة المناسبة.", "Concevoir des trajets autonomes qui s’expliquent au bon moment.", "Ontwerp autonome ritten die op het juiste moment duidelijkheid geven."), t("Trust is built through boarding, route changes, handover and arrival. MOVERA designs information and controls around those moments.\nAccessibility and human factors are system requirements from the start, not a final interface pass.", "تُبنى الثقة عند الصعود وتغيير المسار وانتقال التحكم والوصول. تصمم موفيرا المعلومات وعناصر التحكم حول هذه اللحظات.\nسهولة الوصول والعوامل البشرية متطلبات للنظام منذ البداية، وليست تحسيناً أخيراً للواجهة.", "La confiance naît à l’embarquement, lors d’un changement de route, d’une reprise en main et à l’arrivée. MOVERA conçoit l’information autour de ces moments.\nAccessibilité et facteurs humains sont des exigences du système dès le départ.", "Vertrouwen ontstaat bij instappen, routewijziging, overname en aankomst. MOVERA ontwerpt informatie en bediening rond die momenten.\nToegankelijkheid en human factors zijn van bij de start systeemvereisten."), img.serviceExperience, { category: "Experience", sector: "Vehicle Experience", featured: true, displayOrder: 3, tags: ["human factors", "accessibility", "cockpit"], relatedIds: ["connected-cockpit", "trust-before-boarding"] }),
];

const products: ContentItem[] = [
  item("movera-command", "products", same("MOVERA Command"), t("One operational view for the next mobility decision.", "صورة تشغيلية واحدة تقود قرار التنقل التالي.", "Une vue opérationnelle unique pour décider du prochain mouvement.", "Eén operationeel beeld voor de volgende mobiliteitsbeslissing."), t("Command brings missions, vehicle state, confidence and approvals into a focused workspace. Operators see what changed, why it matters and who owns the next action.\nDispatch, fleet health and incidents share one accountable decision trail.", "تجمع المنصة المهام وحالة المركبات ومؤشرات الثقة والموافقات في مساحة مركزة. يرى المشغّل ما تغيّر ولماذا يهم ومن يملك الإجراء التالي.\nتشترك عمليات التوجيه وصحة الأسطول والحوادث في سجل قرار واحد خاضع للمساءلة.", "Command réunit missions, état des véhicules, confiance et validations dans un espace ciblé. L’opérateur comprend ce qui change, pourquoi et qui agit ensuite.\nDispatching, santé de flotte et incidents partagent une même trace de décision.", "Command brengt opdrachten, voertuigstatus, vertrouwen en goedkeuringen samen. Operatoren zien wat wijzigde, waarom het telt en wie handelt.\nDispatching, vlootconditie en incidenten delen één controleerbaar beslisspoor."), img.productCommand, { category: "Operations platform", sector: "Fleet Operations", featured: true, displayOrder: 0, tags: ["missions", "approvals", "exceptions"], relatedIds: ["fleet-intelligence", "antwerp-fleet-flow"] }),
  item("perception-layer", "products", same("Perception Layer"), t("Make vehicle perception visible, explainable and ready to improve.", "نجعل إدراك المركبة مرئياً وقابلاً للتفسير والتحسين.", "Rendre la perception du véhicule visible, explicable et améliorable.", "Maak voertuigperceptie zichtbaar, uitlegbaar en verbeterbaar."), t("Perception Layer connects sensor context, detections, confidence and review events. Engineers can move from an exception to the exact evidence behind it.\nCompare, annotate and approve verified insight before it returns to development.", "تربط الطبقة سياق المستشعرات والاكتشافات ومستوى الثقة وأحداث المراجعة. ينتقل المهندس من الاستثناء إلى الدليل الدقيق خلفه.\nتُقارن المعرفة الموثقة وتُشرح وتُعتمد قبل إعادتها إلى التطوير.", "Perception Layer relie contexte capteur, détections, confiance et événements de revue. L’ingénieur passe d’une exception à la preuve exacte.\nLes enseignements vérifiés sont comparés, annotés et validés avant de revenir au développement.", "Perception Layer koppelt sensorcontext, detecties, vertrouwen en reviewmomenten. Ingenieurs gaan van een uitzondering naar het exacte bewijs.\nGevalideerde inzichten worden vergeleken, geannoteerd en goedgekeurd vóór ze terugkeren naar ontwikkeling."), img.productPerception, { category: "Vehicle intelligence", sector: "Autonomous Vehicles", featured: true, displayOrder: 1, tags: ["sensors", "confidence", "review"], relatedIds: ["autonomy-systems", "brussels-perception-pilot"] }),
  item("motion-os", "products", same("Motion OS"), t("Coordinate movement across vehicles, routes and service teams.", "ننسّق الحركة بين المركبات والمسارات وفرق الخدمة.", "Coordonner les mouvements entre véhicules, itinéraires et équipes.", "Coördineer beweging tussen voertuigen, routes en serviceteams."), t("Motion OS turns plans into missions with rules for priority, capacity, handover and recovery. Local vehicle decisions stay aligned with network intent.\nNew routes and vehicle types can join without rebuilding the operating backbone.", "يحوّل النظام الخطط إلى مهام بقواعد للأولوية والسعة وانتقال المسؤولية واستعادة الخدمة. وتبقى قرارات المركبات متسقة مع هدف الشبكة.\nيمكن إضافة مسارات ومركبات جديدة من دون إعادة بناء الأساس التشغيلي.", "Motion OS transforme les plans en missions avec des règles de priorité, capacité, relais et reprise. Les décisions locales restent alignées sur le réseau.\nDe nouveaux itinéraires et véhicules rejoignent le service sans reconstruire son socle.", "Motion OS zet plannen om in opdrachten met regels voor prioriteit, capaciteit, overdracht en herstel. Lokale beslissingen blijven afgestemd op het netwerk.\nNieuwe routes en voertuigtypes sluiten aan zonder de operationele ruggengraat opnieuw te bouwen."), img.productMotion, { category: "Orchestration layer", sector: "Connected Infrastructure", featured: true, displayOrder: 2, tags: ["routing", "handover", "orchestration"], relatedIds: ["mobility-operations", "adaptive-mobility-corridor"] }),
  item("mobility-twin", "products", same("Mobility Twin"), t("Rehearse mobility decisions before they reach a live street.", "نختبر قرارات التنقل قبل أن تصل إلى الشارع الفعلي.", "Répéter les décisions de mobilité avant leur arrivée dans la rue.", "Beproef mobiliteitsbeslissingen vóór ze de echte straat bereiken."), t("Mobility Twin combines service rules, fleet state and street context in a shared simulation. Teams test demand, incidents and infrastructure changes before committing resources.\nScenarios are compared through service outcomes and decision quality, not spectacle.", "يجمع التوأم الرقمي قواعد الخدمة وحالة الأسطول وسياق الشارع في محاكاة مشتركة. تختبر الفرق الطلب والحوادث وتغييرات البنية التحتية قبل تخصيص الموارد.\nتُقارن السيناريوهات وفق نتائج الخدمة وجودة القرار، لا وفق الاستعراض.", "Mobility Twin rassemble règles de service, état de flotte et contexte urbain dans une simulation partagée. Les équipes testent demande, incidents et changements avant d’engager les moyens.\nLes scénarios sont comparés par leurs résultats et la qualité des décisions.", "Mobility Twin combineert serviceregels, vlootstatus en straatcontext in één simulatie. Teams testen vraag, incidenten en wijzigingen vóór middelen worden ingezet.\nScenario’s worden vergeleken op service-uitkomst en besliskwaliteit."), img.productTwin, { category: "Simulation", sector: "Mobility Planning", featured: true, displayOrder: 3, tags: ["simulation", "scenarios", "planning"], relatedIds: ["mobility-simulation-studio", "adaptive-mobility-corridor"] }),
];

const projects: ContentItem[] = [
  item("brussels-perception-pilot", "projects", t("Brussels Urban Perception", "إدراك حضري في بروكسل", "Perception urbaine à Bruxelles", "Stedelijke perceptie in Brussel"), t("A reference programme for reading dense Belgian streets with accountable confidence.", "برنامج مرجعي لفهم شوارع بلجيكية كثيفة بدرجات ثقة قابلة للمراجعة.", "Un programme de référence pour lire les rues belges denses avec une confiance vérifiable.", "Een referentieprogramma om drukke Belgische straten te lezen met controleerbaar vertrouwen."), t("The programme studies how a shuttle interprets trams, cyclists, pedestrians, road works and changing weather in one shared street.\nDetections are paired with confidence and operator review so difficult moments become usable engineering evidence.", "يدرس البرنامج كيف تفهم المركبة الترام والدراجات والمشاة والأعمال المؤقتة وتغيّر الطقس في شارع واحد.\nترتبط الاكتشافات بدرجات الثقة ومراجعة المشغّل كي تصبح المواقف الصعبة أدلة هندسية قابلة للاستخدام.", "Le programme étudie la lecture simultanée des trams, cyclistes, piétons, chantiers et changements météo.\nLes détections sont associées à leur confiance et à la revue opérateur afin que les situations difficiles deviennent des preuves utiles.", "Het programma onderzoekt hoe een shuttle trams, fietsers, voetgangers, wegenwerken en wisselend weer interpreteert.\nDetecties worden gekoppeld aan vertrouwen en operatorreview, zodat moeilijke momenten bruikbaar engineeringbewijs worden."), img.projectBrussels, { category: "Reference programme", sector: "Autonomous Vehicles", client: "Urban mobility ecosystem", date: "2026", featured: true, displayOrder: 0, tags: ["Brussels", "perception", "mixed traffic"], relatedIds: ["perception-layer", "autonomy-systems"] }),
  item("antwerp-fleet-flow", "projects", t("Antwerp Fleet Flow", "تدفق الأسطول في أنتويرب", "Flux de flotte à Anvers", "Vlootdoorstroming in Antwerpen"), t("A coordinated service model for electric vehicles in a high-intensity port corridor.", "نموذج خدمة منسق لمركبات كهربائية في ممر مينائي عالي الكثافة.", "Un modèle coordonné pour des véhicules électriques dans un corridor portuaire intensif.", "Een gecoördineerd servicemodel voor elektrische voertuigen in een intensieve havencorridor."), t("Charging windows, vehicle readiness, mission priority and route conditions meet in one dispatch view.\nThe programme helps operators act early, protect service commitments and learn from every exception.", "تجتمع نوافذ الشحن وجاهزية المركبات وأولوية المهام وظروف المسار في صورة توجيه واحدة.\nيساعد البرنامج المشغّلين على التحرك المبكر وحماية الالتزامات والتعلم من كل استثناء.", "Fenêtres de recharge, disponibilité des véhicules, priorité des missions et état des itinéraires se retrouvent dans une même vue.\nLe programme aide les opérateurs à agir tôt, protéger le service et apprendre de chaque exception.", "Laadvensters, voertuiggereedheid, opdrachtprioriteit en routecondities komen samen in één dispatchbeeld.\nHet programma helpt operatoren vroeg handelen, serviceafspraken bewaken en leren van elke uitzondering."), img.projectAntwerp, { category: "Reference programme", sector: "Fleet Operations", client: "Port mobility operators", date: "2026", featured: true, displayOrder: 1, tags: ["Antwerp", "electric fleet", "dispatch"], relatedIds: ["movera-command", "fleet-intelligence"] }),
  item("connected-cockpit", "projects", t("Connected Cockpit", "قمرة القيادة المتصلة", "Cockpit connecté", "Verbonden cockpit"), t("A calmer interface for handover, route change and passenger confidence.", "واجهة أكثر هدوءاً لانتقال التحكم وتغيير المسار وثقة الركاب.", "Une interface plus sereine pour la reprise en main, le changement de route et la confiance.", "Een rustigere interface voor overname, routewijziging en vertrouwen."), t("This design study organises autonomy state, route intent and human control around three questions: what is happening, why and what can I do?\nPersistent visual noise is reduced; strong signals are reserved for moments that need attention.", "تنظم الدراسة حالة القيادة الذاتية وهدف المسار والتحكم البشري حول ثلاثة أسئلة: ماذا يحدث، ولماذا، وماذا أستطيع أن أفعل؟\nتقل الضوضاء البصرية الدائمة وتُحجز الإشارات القوية للحظات التي تستحق الانتباه.", "Cette étude organise l’état d’autonomie, l’intention de route et la reprise humaine autour de trois questions : que se passe-t-il, pourquoi et que puis-je faire ?\nLe bruit visuel permanent diminue; les signaux forts sont réservés aux moments importants.", "Deze studie ordent autonomiestatus, route-intentie en menselijke controle rond drie vragen: wat gebeurt er, waarom en wat kan ik doen?\nPermanente visuele ruis vermindert; sterke signalen blijven voor momenten die aandacht vragen."), img.projectCockpit, { category: "Design study", sector: "Vehicle Experience", client: "Vehicle platform teams", date: "2026", featured: true, displayOrder: 2, tags: ["cockpit", "handover", "accessibility"], relatedIds: ["vehicle-experience", "trust-before-boarding"] }),
  item("adaptive-mobility-corridor", "projects", t("Adaptive Mobility Corridor", "ممر تنقل متكيّف", "Corridor de mobilité adaptatif", "Adaptieve mobiliteitscorridor"), t("A corridor blueprint for public transport, shuttles, cyclists and accessible stops.", "تصور لممر ينسق النقل العام والمركبات والدراجات والمحطات المهيأة.", "Un schéma de corridor coordonnant transport public, navettes, cyclistes et arrêts accessibles.", "Een corridorconcept voor openbaar vervoer, shuttles, fietsers en toegankelijke haltes."), t("Vehicles and roadside infrastructure operate as one service system. Capacity, accessibility and local conditions guide how missions adapt.\nA shared simulation lets public and private operators examine trade-offs before changing street operations.", "تعمل المركبات والبنية التحتية على الطريق كنظام خدمة واحد. وتوجّه السعة وسهولة الوصول والظروف المحلية كيفية تكيف المهام.\nتتيح المحاكاة المشتركة للمشغّلين فهم المفاضلات قبل تغيير التشغيل في الشارع.", "Véhicules et infrastructure routière fonctionnent comme un même système. Capacité, accessibilité et contexte local font évoluer les missions.\nUne simulation partagée permet d’examiner les arbitrages avant de modifier l’exploitation.", "Voertuigen en weginfrastructuur werken als één servicesysteem. Capaciteit, toegankelijkheid en lokale omstandigheden sturen de opdrachten.\nEen gedeelde simulatie laat operatoren afwegingen onderzoeken vóór de straatwerking verandert."), img.projectCorridor, { category: "Corridor blueprint", sector: "Connected Infrastructure", client: "Mobility authorities and operators", date: "2026", featured: true, displayOrder: 3, tags: ["infrastructure", "accessibility", "simulation"], relatedIds: ["motion-os", "mobility-twin"] }),
];

const news: ContentItem[] = [
  item("introducing-movera", "news", t("Introducing MOVERA", "هذه هي موفيرا", "MOVERA entre en mouvement", "MOVERA komt in beweging"), t("A Belgian platform for the decisions behind autonomous and connected mobility.", "منصة بلجيكية للقرارات التي تقود التنقل الذاتي والمتصل.", "Une plateforme belge dédiée aux décisions qui font avancer la mobilité autonome et connectée.", "Een Belgisch platform voor de beslissingen achter autonome en verbonden mobiliteit."), t("Intelligent mobility only matters when operators, engineers and passengers understand what the system is doing.\nMOVERA connects vehicle perception, fleet operations and human judgment for real Belgian mobility conditions.", "لا قيمة للتنقل الذكي ما لم يفهم المشغّلون والمهندسون والركاب ما يفعله النظام.\nتربط موفيرا إدراك المركبة بعمليات الأسطول والحكم البشري ضمن واقع التنقل في بلجيكا.", "La mobilité intelligente n’a de valeur que si opérateurs, ingénieurs et passagers comprennent le système.\nMOVERA relie perception véhicule, opérations de flotte et jugement humain pour les réalités belges.", "Intelligente mobiliteit telt pas wanneer operatoren, ingenieurs en passagiers begrijpen wat het systeem doet.\nMOVERA verbindt voertuigperceptie, vlootoperaties en menselijk oordeel voor de Belgische mobiliteitsrealiteit."), img.newsIntro, { category: "Company", date: "2026-08-19", featured: true, displayOrder: 0, tags: ["MOVERA", "Belgium", "mobility"] }),
  item("edge-intelligence-near-movement", "news", t("Intelligence belongs near movement", "الذكاء الأقرب إلى الحركة", "L’intelligence au plus près du mouvement", "Intelligentie dicht bij de beweging"), t("Why useful vehicle intelligence combines edge response with accountable operations.", "لماذا يجمع ذكاء المركبة بين الاستجابة الطرفية والعمليات الخاضعة للمساءلة.", "Pourquoi l’intelligence véhicule associe réaction locale et opérations responsables.", "Waarom voertuigintelligentie lokale respons koppelt aan verantwoordelijke operaties."), t("Fast vehicle decisions belong close to the sensor; service decisions still need context, ownership and evidence.\nMOVERA keeps the response local where latency matters and shared where accountability matters.", "تُتخذ قرارات المركبة السريعة بالقرب من المستشعر، بينما تحتاج قرارات الخدمة إلى السياق والمسؤولية والدليل.\nتُبقي موفيرا الاستجابة محلية عندما يهم الزمن ومشتركة عندما تهم المساءلة.", "Les décisions rapides restent proches du capteur; les décisions de service exigent contexte, responsabilité et preuve.\nMOVERA garde la réponse locale quand la latence compte et partagée quand la responsabilité compte.", "Snelle voertuigbeslissingen horen dicht bij de sensor; servicebeslissingen vragen context, eigenaarschap en bewijs.\nMOVERA houdt respons lokaal waar latency telt en gedeeld waar verantwoordelijkheid telt."), img.newsEdge, { category: "Technology", date: "2026-08-12", featured: true, displayOrder: 1, tags: ["edge", "operations", "accountability"] }),
  item("belgium-shared-mobility-language", "news", t("Belgium needs a shared mobility language", "بلجيكا تحتاج لغة مشتركة للتنقل", "La Belgique a besoin d’un langage commun de la mobilité", "België heeft een gedeelde mobiliteitstaal nodig"), t("Vehicles, authorities and operators move better when service meaning is shared.", "تتحرك المركبات والجهات العامة والمشغّلون بكفاءة أكبر عندما تتوحد معاني الخدمة.", "Véhicules, autorités et opérateurs avancent mieux lorsqu’ils partagent le sens du service.", "Voertuigen, overheden en operatoren werken beter wanneer servicetaal gedeeld is."), t("Belgian regions and transport modes bring different systems and responsibilities to the same journey. A shared operational language reduces friction without erasing local context.\nMOVERA structures missions, exceptions and evidence so each partner keeps its role while collaborating on the same movement.", "تجمع الرحلة في بلجيكا أنظمة ومسؤوليات مختلفة بين المناطق ووسائل النقل. تقلل اللغة التشغيلية المشتركة الاحتكاك من دون إلغاء السياق المحلي.\nتنظم موفيرا المهام والاستثناءات والأدلة بحيث يحافظ كل طرف على دوره ويتعاون الجميع حول الحركة نفسها.", "Les régions et modes belges apportent des systèmes et responsabilités différents à un même trajet. Un langage commun réduit les frictions sans effacer le contexte local.\nMOVERA structure missions, exceptions et preuves afin que chaque partenaire garde son rôle.", "Belgische regio’s en vervoersmodi brengen verschillende systemen en verantwoordelijkheden samen. Een gedeelde taal vermindert wrijving zonder lokale context te wissen.\nMOVERA structureert opdrachten, uitzonderingen en bewijs zodat elke partner zijn rol behoudt."), img.newsBelgium, { category: "Belgium", date: "2026-08-05", featured: true, displayOrder: 2, tags: ["Belgium", "interoperability", "partnership"] }),
];

const blogs: ContentItem[] = [
  item("designing-operator-confidence", "blogs", t("Designing operator confidence", "كيف نصمم ثقة المشغّل", "Concevoir la confiance de l’opérateur", "Operatorvertrouwen ontwerpen"), t("A clear exception is more useful than a crowded real-time dashboard.", "الاستثناء الواضح أنفع من لوحة حية مزدحمة.", "Une exception claire vaut mieux qu’un tableau de bord surchargé.", "Een duidelijke uitzondering is waardevoller dan een druk dashboard."), t("Operator confidence comes from knowing what changed, how certain the system is and which action remains available.\nNormal movement stays quiet; uncertainty appears with evidence; irreversible actions ask for deliberate confirmation.", "تأتي ثقة المشغّل من معرفة ما تغيّر ومدى يقين النظام وما الإجراءات المتاحة.\nتبقى الحركة الطبيعية هادئة، ويظهر عدم اليقين مع دليله، وتتطلب الإجراءات غير القابلة للتراجع تأكيداً مقصوداً.", "La confiance vient de la compréhension du changement, du niveau de certitude et des actions possibles.\nLe normal reste discret, l’incertitude arrive avec sa preuve et l’irréversible demande une confirmation délibérée.", "Vertrouwen komt van begrijpen wat wijzigde, hoe zeker het systeem is en welke actie mogelijk blijft.\nNormale beweging blijft stil, onzekerheid verschijnt met bewijs en onomkeerbare acties vragen bewuste bevestiging."), img.blogOperator, { category: "Operations design", date: "2026-08-16", featured: true, displayOrder: 0, tags: ["operators", "exceptions", "human factors"] }),
  item("trust-before-boarding", "blogs", t("Trust begins before boarding", "الثقة تبدأ قبل الصعود", "La confiance commence avant l’embarquement", "Vertrouwen begint vóór het instappen"), t("Autonomous journeys need a service language passengers recognise before the doors open.", "تحتاج الرحلات الذاتية إلى لغة خدمة يفهمها الراكب قبل أن تُفتح الأبواب.", "Un trajet autonome a besoin d’un langage compris avant l’ouverture des portes.", "Een autonome rit heeft servicetaal nodig die reizigers herkennen vóór de deuren openen."), t("People judge a service through arrival, identity, accessibility and support before they inspect the technology. Those cues should stay consistent from stop to cabin.\nWhen a route changes or the vehicle asks for help, the same language must explain why and what happens next.", "يقيّم الناس الخدمة من طريقة الوصول والهوية وسهولة الاستخدام والدعم قبل التفكير في التقنية. يجب أن تبقى هذه الإشارات متسقة من المحطة إلى المقصورة.\nعندما يتغير المسار أو تطلب المركبة مساعدة، ينبغي للغة نفسها أن تشرح السبب والخطوة التالية.", "Les personnes jugent un service par son arrivée, son identité, son accessibilité et son assistance avant la technologie. Ces repères restent cohérents de l’arrêt à l’habitacle.\nSi la route change ou si le véhicule demande de l’aide, le même langage explique pourquoi et ce qui suit.", "Mensen beoordelen een dienst op aankomst, herkenbaarheid, toegankelijkheid en ondersteuning vóór de technologie. Die signalen blijven van halte tot cabine consistent.\nWanneer de route wijzigt of het voertuig hulp vraagt, legt dezelfde taal uit waarom en wat volgt."), img.blogTrust, { category: "Passenger experience", date: "2026-08-09", featured: true, displayOrder: 1, tags: ["trust", "accessibility", "service design"] }),
  item("from-signals-to-decisions", "blogs", t("From signals to decisions", "من الإشارات إلى القرارات", "Des signaux aux décisions", "Van signalen naar beslissingen"), t("The useful unit of mobility intelligence is not a prediction. It is a better decision.", "وحدة القيمة في ذكاء التنقل ليست التنبؤ، بل القرار الأفضل.", "L’unité utile de l’intelligence mobilité n’est pas la prédiction, mais la meilleure décision.", "De nuttige eenheid van mobiliteitsintelligentie is geen voorspelling, maar een betere beslissing."), t("A signal becomes operational intelligence only with context, confidence, consequence and an owner. Without those elements, more data creates more monitoring work.\nMOVERA shows where automation helps, where policy applies and where a person must decide.", "لا تصبح الإشارة ذكاءً تشغيلياً إلا مع السياق ودرجة الثقة والأثر وصاحب القرار. من دون ذلك، تزيد البيانات عبء المراقبة.\nتوضح موفيرا أين تفيد الأتمتة، وأين تُطبّق السياسة، وأين يجب أن يحسم الإنسان.", "Un signal devient intelligence opérationnelle avec contexte, confiance, conséquence et responsable. Sans eux, davantage de données signifie davantage de surveillance.\nMOVERA montre où l’automatisation aide, où la règle s’applique et où une personne décide.", "Een signaal wordt operationele intelligentie met context, vertrouwen, gevolg en een eigenaar. Zonder die elementen zorgt meer data voor meer monitoring.\nMOVERA toont waar automatisering helpt, beleid geldt en een mens beslist."), img.blogSignals, { category: "Mobility intelligence", date: "2026-08-02", featured: true, displayOrder: 2, tags: ["decisions", "evidence", "governance"] }),
];

const innovation: ContentItem[] = [
  item("confidence-maps", "innovation", t("Confidence Maps", "خرائط الثقة", "Cartes de confiance", "Vertrouwenskaarten"), t("Show where vehicle perception is strong, uncertain or changing.", "نوضح أين يكون إدراك المركبة قوياً أو متردداً أو متغيراً.", "Montrer où la perception est solide, incertaine ou changeante.", "Toon waar voertuigperceptie sterk, onzeker of veranderlijk is."), t("Confidence Maps combines environmental context, model confidence and review evidence without pretending uncertainty has disappeared.\nThe research supports safer testing, sharper annotation and better release decisions.", "تجمع خرائط الثقة السياق البيئي وثقة النموذج وأدلة المراجعة من دون الادعاء بأن عدم اليقين اختفى.\nويدعم البحث اختبارات أكثر أماناً وتعليقات أدق وقرارات إطلاق أفضل.", "Confidence Maps associe contexte, confiance du modèle et preuves de revue sans masquer l’incertitude.\nLa recherche soutient des essais plus sûrs, une annotation plus précise et de meilleures décisions.", "Confidence Maps combineert omgevingscontext, modelvertrouwen en reviewbewijs zonder onzekerheid weg te poetsen.\nHet onderzoek ondersteunt veiliger testen, scherpere annotatie en betere vrijgavebeslissingen."), img.innovationConfidence, { category: "Applied research", sector: "Autonomous Vehicles", featured: true, displayOrder: 0, tags: ["confidence", "perception", "validation"] }),
  item("mobility-simulation-studio", "innovation", t("Mobility Simulation Studio", "استوديو محاكاة التنقل", "Studio de simulation mobilité", "Mobiliteitssimulatiestudio"), t("Rehearse service changes before people and vehicles meet them on the street.", "نختبر تغييرات الخدمة قبل أن يواجهها الناس والمركبات في الشارع.", "Répéter les changements de service avant leur arrivée dans la rue.", "Beproef servicewijzigingen vóór mensen en voertuigen ze op straat ervaren."), t("Planners, operators, engineers and designers inspect the same scenarios together. Demand, incidents, accessibility and fleet constraints become visible trade-offs.\nThe goal is a disciplined environment for making better decisions earlier.", "يفحص المخططون والمشغّلون والمهندسون والمصممون السيناريوهات نفسها معاً. فتتحول متطلبات الطلب والحوادث وسهولة الوصول وقيود الأسطول إلى مفاضلات واضحة.\nالهدف بيئة منضبطة لاتخاذ قرارات أفضل في وقت أبكر.", "Planificateurs, opérateurs, ingénieurs et designers examinent les mêmes scénarios. Demande, incidents, accessibilité et contraintes deviennent des arbitrages visibles.\nL’objectif est un cadre rigoureux pour mieux décider plus tôt.", "Planners, operatoren, ingenieurs en ontwerpers onderzoeken dezelfde scenario’s. Vraag, incidenten, toegankelijkheid en vlootbeperkingen worden zichtbare afwegingen.\nHet doel is een gedisciplineerde omgeving om vroeger beter te beslissen."), img.innovationSimulation, { category: "Simulation", sector: "Mobility Planning", featured: true, displayOrder: 1, tags: ["simulation", "planning", "collaboration"] }),
  item("curb-intelligence", "innovation", t("Curb Intelligence", "ذكاء حافة الطريق", "Intelligence du bord de voirie", "Intelligente stoeprand"), t("Study the street decisions that shape access, safety and service reliability.", "ندرس قرارات الشارع التي تصنع سهولة الوصول والسلامة وموثوقية الخدمة.", "Étudier les décisions de voirie qui façonnent accès, sécurité et fiabilité.", "Onderzoek straatbeslissingen die toegang, veiligheid en betrouwbaarheid bepalen."), t("Pick-up space, deliveries, cycles and accessible boarding compete at the same kerb. Live context and clear service rules can reduce conflict.\nPublic-space outcomes stay visible alongside vehicle efficiency.", "تتنافس مساحة الصعود والتوصيل والدراجات والصعود المهيأ على الحافة نفسها. يمكن للسياق الحي وقواعد الخدمة الواضحة أن تقلل التعارض.\nيبقى أثر الحل على الفضاء العام ظاهراً إلى جانب كفاءة المركبات.", "Prise en charge, livraisons, vélos et embarquement accessible partagent le même bord de voirie. Le contexte en direct et des règles claires réduisent les conflits.\nLes résultats pour l’espace public restent visibles avec l’efficacité des véhicules.", "Oppikken, leveringen, fietsen en toegankelijk instappen delen dezelfde stoeprand. Live context en duidelijke regels verminderen conflicten.\nDe uitkomst voor de publieke ruimte blijft even zichtbaar als voertuigefficiëntie."), img.innovationCurb, { category: "Street research", sector: "Connected Infrastructure", featured: true, displayOrder: 2, tags: ["curb", "accessibility", "public space"] }),
];

const jobs: ContentItem[] = [
  item("autonomy-systems-engineer", "jobs", t("Autonomy Systems Engineer", "مهندس أنظمة القيادة الذاتية", "Ingénieur·e systèmes autonomes", "Autonomy Systems Engineer"), t("Turn perception and planning behaviour into testable vehicle evidence.", "حوّل سلوك الإدراك والتخطيط إلى أدلة قابلة للاختبار على المركبة.", "Transformer perception et planification en preuves vérifiables sur véhicule.", "Zet perceptie- en planningsgedrag om in testbaar voertuigbewijs."), t("Connect vehicle software, sensor context and road-test workflows. Move between system behaviour, field evidence and clear technical decisions.\nWork with product, safety and operations colleagues in Belgium to make difficult autonomy moments reproducible.", "اربط برمجيات المركبة بسياق المستشعرات ومسارات الاختبار الميداني، وانتقل بين سلوك النظام والدليل العملي والقرار التقني الواضح.\nاعمل مع فرق المنتج والسلامة والعمليات في بلجيكا لجعل المواقف الصعبة قابلة للتكرار.", "Reliez logiciel véhicule, contexte capteur et parcours d’essai. Passez du comportement système à la preuve terrain et à la décision claire.\nTravaillez avec produit, sécurité et opérations en Belgique pour rendre les situations difficiles reproductibles.", "Verbind voertuigsoftware, sensorcontext en wegtestflows. Schakel tussen systeemgedrag, veldbewijs en heldere technische beslissingen.\nWerk met product-, safety- en operationele collega’s in België om moeilijke momenten reproduceerbaar te maken."), img.careersTeam, { category: "Engineering", region: "hub-a", displayOrder: 0, tags: ["hybrid", "Belgium", "autonomy"] }),
  item("mobility-data-engineer", "jobs", t("Mobility Data Engineer", "مهندس بيانات التنقل", "Ingénieur·e data mobilité", "Mobility Data Engineer"), t("Build the signal layer behind fleet, vehicle and street decisions.", "ابنِ طبقة الإشارات خلف قرارات الأسطول والمركبة والشارع.", "Construire la couche de signaux derrière les décisions de flotte, véhicule et voirie.", "Bouw de signaallaag achter vloot-, voertuig- en straatbeslissingen."), t("Shape event models, quality controls and data products trusted by operators and engineers. The work spans streaming signals, operational context and review evidence.\nWe value thoughtful modelling, observability and plain explanations over clever pipelines understood by one person.", "صمّم نماذج الأحداث وضوابط الجودة ومنتجات البيانات التي يثق بها المشغّلون والمهندسون. ويشمل العمل الإشارات المتدفقة والسياق التشغيلي وأدلة المراجعة.\nنقدّر النمذجة المتأنية وقابلية الرصد والشرح المباشر أكثر من مسارات لا يفهمها سوى شخص واحد.", "Façonnez modèles d’événements, contrôles qualité et produits data fiables. Le travail couvre flux de signaux, contexte opérationnel et preuves.\nNous privilégions une modélisation réfléchie, l’observabilité et des explications simples aux pipelines compris par une seule personne.", "Vorm eventmodellen, kwaliteitscontroles en dataproducten die operatoren en ingenieurs vertrouwen. Het werk omvat streamingsignalen, context en reviewbewijs.\nWe waarderen doordachte modellering, observeerbaarheid en duidelijke uitleg boven pipelines die maar één persoon begrijpt."), img.careersData, { category: "Data", region: "hub-b", displayOrder: 1, tags: ["hybrid", "Belgium", "data"] }),
  item("systems-integration-lead", "jobs", t("Systems Integration Lead", "قائد تكامل الأنظمة", "Responsable intégration systèmes", "Lead Systeemintegratie"), t("Coordinate the interfaces, evidence and people behind an end-to-end mobility service.", "نسّق الواجهات والأدلة والفرق خلف خدمة تنقل متكاملة.", "Coordonner interfaces, preuves et équipes pour un service de bout en bout.", "Coördineer interfaces, bewijs en mensen achter een end-to-end mobiliteitsdienst."), t("Lead integration across vehicles, cloud services, operator workflows and roadside systems. Turn cross-team ambiguity into an executable test plan.\nBring calm structure to complex programmes and communicate with engineers, service owners and partners.", "تولَّ قيادة التكامل بين المركبات والخدمات السحابية ومسارات المشغّلين وأنظمة الطريق، وحوّل الغموض بين الفرق إلى خطة اختبار قابلة للتنفيذ.\nامنح البرامج المعقدة هيكلاً هادئاً وتواصل مع المهندسين ومالكي الخدمات والشركاء.", "Pilotez l’intégration entre véhicules, services cloud, parcours opérateurs et systèmes routiers. Transformez l’ambiguïté en plan d’essai exécutable.\nApportez une structure sereine aux programmes complexes et dialoguez avec ingénieurs, responsables et partenaires.", "Leid integratie tussen voertuigen, clouddiensten, operatorflows en wegsystemen. Zet onduidelijkheid om in een uitvoerbaar testplan.\nBreng rustige structuur in complexe programma’s en communiceer met engineers, service-eigenaars en partners."), img.careersIntegration, { category: "Delivery", region: "hub-c", displayOrder: 2, tags: ["hybrid", "Belgium", "integration"] }),
];

const aboutPagesSeed: ContentItem[] = [
  page("who-we-are", t("Who we are", "من نحن", "Qui sommes-nous", "Wie we zijn"), t("A Belgian mobility platform built around clear, accountable movement.", "منصة تنقل بلجيكية تُبنى حول حركة واضحة وخاضعة للمساءلة.", "Une plateforme belge de mobilité fondée sur des mouvements clairs et responsables.", "Een Belgisch mobiliteitsplatform voor duidelijke, verantwoorde beweging."), t("MOVERA brings vehicle engineering, operations, service design and applied intelligence into one team. We focus on the decisions that connect a capable vehicle to a dependable mobility service.", "تجمع موفيرا هندسة المركبات والعمليات وتصميم الخدمات والذكاء التطبيقي ضمن فريق واحد. نركز على القرارات التي تربط مركبة قادرة بخدمة تنقل يمكن الاعتماد عليها.", "MOVERA réunit ingénierie véhicule, opérations, design de service et intelligence appliquée. Nous travaillons sur les décisions qui relient un véhicule capable à un service fiable.", "MOVERA brengt voertuigengineering, operaties, serviceontwerp en toegepaste intelligentie samen. We focussen op de beslissingen die een bekwaam voertuig verbinden met een betrouwbare dienst."), img.aboutStudio, { aboutLayout: "story", displayOrder: 0, sections: [section("purpose", t("Movement people can understand", "حركة يفهمها الناس", "Un mouvement que chacun comprend", "Beweging die mensen begrijpen"), t("We make system state, uncertainty and responsibility visible to the people who operate and use mobility services.", "نجعل حالة النظام وعدم اليقين والمسؤولية واضحة لمن يشغّلون خدمات التنقل ويستخدمونها.", "Nous rendons l’état du système, l’incertitude et la responsabilité visibles pour celles et ceux qui opèrent et utilisent la mobilité.", "We maken systeemstatus, onzekerheid en verantwoordelijkheid zichtbaar voor wie mobiliteitsdiensten uitbaat en gebruikt.")), section("method", t("Evidence before theatre", "الدليل قبل الاستعراض", "La preuve avant le spectacle", "Bewijs vóór spektakel"), t("We prefer measurable service behaviour, traceable decisions and calm interfaces to technology that merely looks advanced.", "نفضّل سلوك الخدمة القابل للقياس والقرارات القابلة للتتبع والواجهات الهادئة على تقنية تبدو متقدمة بلا أثر حقيقي.", "Nous préférons un service mesurable, des décisions traçables et des interfaces sereines à une technologie seulement spectaculaire.", "We kiezen voor meetbaar servicegedrag, traceerbare beslissingen en rustige interfaces boven technologie die alleen geavanceerd oogt."))] }),
  page("history", t("How MOVERA moves", "كيف تتقدم موفيرا", "Le mouvement MOVERA", "Hoe MOVERA beweegt"), t("A company shaped by vehicle craft, operational evidence and Belgian mobility complexity.", "شركة تصوغها خبرة المركبات والدليل التشغيلي وتعقيد التنقل في بلجيكا.", "Une entreprise façonnée par le savoir-faire véhicule, la preuve opérationnelle et la complexité belge.", "Een bedrijf gevormd door voertuigvakmanschap, operationeel bewijs en Belgische mobiliteitscomplexiteit."), t("MOVERA follows a clear progression: observe the movement, understand the decision, coordinate the service and learn from evidence.", "تسير موفيرا في تسلسل واضح: نرصد الحركة، ونفهم القرار، وننسق الخدمة، ثم نتعلم من الدليل.", "MOVERA suit une progression simple : observer le mouvement, comprendre la décision, coordonner le service et apprendre de la preuve.", "MOVERA volgt een heldere lijn: beweging waarnemen, de beslissing begrijpen, de dienst coördineren en leren uit bewijs."), img.aboutHistory, { aboutLayout: "timeline", displayOrder: 1, timeline: [
    { id: "observe", label: t("01 · Observe", "01 · نرصد", "01 · Observer", "01 · Waarnemen"), title: t("Start with the real street", "نبدأ من الشارع الحقيقي", "Commencer dans la vraie rue", "Begin bij de echte straat"), body: t("Ground every product decision in conditions vehicles, operators and passengers actually meet.", "نربط كل قرار منتج بالظروف التي تواجهها المركبات والمشغّلون والركاب فعلاً.", "Ancrer chaque décision produit dans les conditions réellement rencontrées.", "Veranker elke productbeslissing in de omstandigheden die voertuigen, operatoren en passagiers echt ervaren."), media: img.aboutHistory },
    { id: "decide", label: t("02 · Decide", "02 · نقرر", "02 · Décider", "02 · Beslissen"), title: t("Build the decision layer", "نبني طبقة القرار", "Construire la couche de décision", "Bouw de beslislaag"), body: t("Connect perception, service rules and human authority so movement can scale responsibly.", "نربط الإدراك وقواعد الخدمة والقرار البشري كي تتوسع الحركة بمسؤولية.", "Relier perception, règles de service et autorité humaine pour grandir de manière responsable.", "Verbind perceptie, serviceregels en menselijke bevoegdheid zodat beweging verantwoord kan opschalen."), media: img.productCommand },
    { id: "learn", label: t("03 · Learn", "03 · نتعلم", "03 · Apprendre", "03 · Leren"), title: t("Make mobility learn", "نجعل التنقل يتعلم", "Faire apprendre la mobilité", "Laat mobiliteit leren"), body: t("Turn verified operational evidence into safer systems and stronger services.", "نحوّل الدليل التشغيلي الموثق إلى أنظمة أكثر أماناً وخدمات أقوى.", "Transformer les preuves vérifiées en systèmes plus sûrs et services plus solides.", "Zet gevalideerd operationeel bewijs om in veiligere systemen en sterkere diensten."), media: img.innovationConfidence },
  ] }),
  page("vision-mission", t("Vision and mission", "الرؤية والرسالة", "Vision et mission", "Visie en missie"), t("Move intelligence into the real world without losing human understanding.", "ننقل الذكاء إلى العالم الحقيقي من دون أن نفقد وضوحه للإنسان.", "Mettre l’intelligence en mouvement sans perdre la compréhension humaine.", "Breng intelligentie naar de echte wereld zonder menselijk begrip te verliezen."), t("Our vision is mobility that feels more capable because it is easier to understand, operate and trust. Our mission is to build the systems and working practices that make that possible.", "رؤيتنا تنقل أكثر قدرة لأنه أسهل فهماً وتشغيلاً وثقة. ورسالتنا بناء الأنظمة وأساليب العمل التي تحقق ذلك.", "Notre vision : une mobilité plus capable parce qu’elle est plus simple à comprendre, opérer et croire. Notre mission : construire les systèmes et pratiques qui la rendent possible.", "Onze visie is mobiliteit die meer kan omdat ze eenvoudiger te begrijpen, bedienen en vertrouwen is. Onze missie is de systemen en werkwijzen bouwen die dat mogelijk maken."), img.innovationSimulation, { aboutLayout: "vision", displayOrder: 2, sections: [section("vision", t("Vision", "الرؤية", "Vision", "Visie"), t("A connected ecosystem where every important movement can be understood and improved.", "منظومة متصلة يمكن فهم كل حركة مهمة فيها وتحسينها.", "Un écosystème connecté où chaque mouvement important peut être compris et amélioré.", "Een verbonden ecosysteem waarin elke belangrijke beweging begrepen en verbeterd kan worden.")), section("mission", t("Mission", "الرسالة", "Mission", "Missie"), t("Give vehicle teams and operators one accountable path from signal to decision.", "نمنح فرق المركبات والمشغّلين مساراً واحداً خاضعاً للمساءلة من الإشارة إلى القرار.", "Donner aux équipes véhicule et aux opérateurs un chemin responsable du signal à la décision.", "Geef voertuigteams en operatoren één verantwoord pad van signaal naar beslissing."))] }),
  page("clients-certificates", t("Partnership and assurance", "الشراكة والضمان", "Partenariats et assurance", "Partnerschap en zekerheid"), t("A practical framework for working across vehicles, infrastructure, operations and public space.", "إطار عملي للتعاون بين المركبات والبنية التحتية والعمليات والفضاء العام.", "Un cadre concret pour collaborer entre véhicules, infrastructure, opérations et espace public.", "Een praktisch kader voor samenwerking tussen voertuigen, infrastructuur, operaties en publieke ruimte."), t("MOVERA builds partnerships around explicit roles, shared evidence and traceable decisions. Assurance grows from how work is governed, tested and operated.", "تبني موفيرا شراكاتها على أدوار صريحة وأدلة مشتركة وقرارات قابلة للتتبع. وينشأ الضمان من طريقة إدارة العمل واختباره وتشغيله.", "MOVERA fonde ses partenariats sur des rôles explicites, des preuves partagées et des décisions traçables. L’assurance vient de la gouvernance, des essais et de l’exploitation.", "MOVERA bouwt partnerschappen rond expliciete rollen, gedeeld bewijs en traceerbare beslissingen. Zekerheid groeit uit de manier waarop werk bestuurd, getest en uitgebaat wordt."), img.newsBelgium, { aboutLayout: "certificates", displayOrder: 3, credentials: [
    { id: "shared-evidence", title: t("Shared evidence", "دليل مشترك", "Preuve partagée", "Gedeeld bewijs"), issuer: t("Delivery practice", "منهج التنفيذ", "Pratique de réalisation", "Realisatiepraktijk"), description: t("Partners work from agreed tests, decision records and service outcomes.", "يعمل الشركاء انطلاقاً من اختبارات متفق عليها وسجلات قرار ونتائج خدمة واضحة.", "Les partenaires s’appuient sur des essais convenus, des traces de décision et des résultats de service.", "Partners werken met afgesproken tests, beslisregistraties en service-uitkomsten."), media: img.newsBelgium },
    { id: "responsible-automation", title: t("Responsible automation", "أتمتة مسؤولة", "Automatisation responsable", "Verantwoorde automatisering"), issuer: t("Operating principle", "مبدأ تشغيلي", "Principe opérationnel", "Operationeel principe"), description: t("Automation has visible limits, escalation paths and human authority.", "للأتمتة حدود واضحة ومسارات تصعيد وسلطة بشرية معروفة.", "L’automatisation possède des limites visibles, des voies d’escalade et une autorité humaine.", "Automatisering heeft zichtbare grenzen, escalatiepaden en menselijke bevoegdheid."), media: img.innovationConfidence },
  ] }),
  page("ceo-message", t("Leadership note", "رسالة القيادة", "Message de la direction", "Boodschap van het leiderschap"), t("Why MOVERA puts understanding at the centre of intelligent movement.", "لماذا تضع موفيرا الفهم في قلب الحركة الذكية.", "Pourquoi MOVERA place la compréhension au cœur du mouvement intelligent.", "Waarom MOVERA begrip centraal stelt in intelligente beweging."), t("Mobility earns trust when capability and responsibility move together.", "يكسب التنقل الثقة عندما تتقدم القدرة والمسؤولية معاً.", "La mobilité gagne la confiance lorsque capacité et responsabilité avancent ensemble.", "Mobiliteit verdient vertrouwen wanneer vermogen en verantwoordelijkheid samen bewegen."), img.projectBrussels, { displayOrder: 4 }),
  page("leadership", t("Leadership", "القيادة", "Direction", "Leiderschap"), t("Disciplines that hold product ambition, engineering evidence and service responsibility together.", "تخصصات تجمع طموح المنتج والدليل الهندسي ومسؤولية الخدمة.", "Des disciplines qui relient ambition produit, preuve d’ingénierie et responsabilité de service.", "Disciplines die productambitie, engineeringbewijs en serviceverantwoordelijkheid samenhouden."), t("MOVERA is led through complementary responsibilities rather than personality profiles. Direction remains close to engineering, operations and the people who experience the service.", "تُقاد موفيرا عبر مسؤوليات متكاملة لا عبر صور فردية. وتبقى القيادة قريبة من الهندسة والعمليات ومن الناس الذين يعيشون الخدمة.", "MOVERA est dirigée par des responsabilités complémentaires plutôt que par des profils individuels. La direction reste proche de l’ingénierie, des opérations et des personnes qui vivent le service.", "MOVERA wordt geleid vanuit complementaire verantwoordelijkheden, niet vanuit persoonsprofielen. De leiding blijft dicht bij engineering, operaties en de mensen die de dienst ervaren."), img.careersTeam, { aboutLayout: "leadership", displayOrder: 5, profiles: [
    { id: "strategy", name: t("Mobility Strategy", "استراتيجية التنقل", "Stratégie mobilité", "Mobiliteitsstrategie"), role: t("Direction and partnerships", "الاتجاه والشراكات", "Direction et partenariats", "Richting en partnerschappen"), summary: t("Connects public value, service intent and a clear route to deployment.", "تربط القيمة العامة بهدف الخدمة ومسار واضح للتطبيق.", "Relie valeur publique, intention de service et chemin de déploiement.", "Verbindt publieke waarde, service-intentie en een helder implementatiepad."), portrait: img.careersTeam },
    { id: "engineering", name: t("Autonomy Engineering", "هندسة القيادة الذاتية", "Ingénierie autonome", "Autonomie-engineering"), role: t("Systems and evidence", "الأنظمة والأدلة", "Systèmes et preuves", "Systemen en bewijs"), summary: t("Turns perception and vehicle behaviour into testable, accountable systems.", "تحوّل الإدراك وسلوك المركبة إلى أنظمة قابلة للاختبار والمساءلة.", "Transforme perception et comportement véhicule en systèmes testables et responsables.", "Zet perceptie en voertuiggedrag om in testbare, verantwoordelijke systemen."), portrait: img.careersIntegration },
    { id: "operations", name: t("Product Operations", "عمليات المنتج", "Opérations produit", "Productoperaties"), role: t("Service and experience", "الخدمة والتجربة", "Service et expérience", "Service en ervaring"), summary: t("Keeps operator workflows, passenger experience and product decisions aligned.", "تُبقي مسارات المشغّلين وتجربة الركاب وقرارات المنتج في اتجاه واحد.", "Aligne parcours opérateurs, expérience passager et décisions produit.", "Houdt operatorflows, passagierservaring en productbeslissingen op één lijn."), portrait: img.blogOperator },
  ] }),
];

